{
  "themes": [
    {
      "cluster": 24,
      "name": "OnePlus Exchange and EMI Issues",
      "description": "Customers report problems with OnePlus phone exchange offers, out‑of‑stock items, and higher‑than‑advertised EMI rates."
    },
    {
      "cluster": 25,
      "name": "Excessive Packaging Waste",
      "description": "Customers complain that product packaging uses overly large cardboard boxes, creating unnecessary waste."
    },
    {
      "cluster": 26,
      "name": "Unexpected or Duplicate Charges",
      "description": "Customers see extra or duplicate payments on their accounts, especially for unused services or returned items."
    },
    {
      "cluster": 27,
      "name": "Gift Card Balance Errors",
      "description": "Customers experience gift cards not applying correctly, missing balances, or invalid voucher codes."
    },
    {
      "cluster": 28,
      "name": "Amazon Pay Withdrawal and Transfer Issues",
      "description": "Customers ask how to move money from Amazon Pay to a bank account or why funds are being held."
    },
    {
      "cluster": 29,
      "name": "Missing Cashback Rewards",
      "description": "Customers report that promised cashback from card or promotional offers has not been credited."
    },
    {
      "cluster": 30,
      "name": "Wrong or Damaged Product Delivery",
      "description": "Customers receive incorrect, damaged, or mis‑described items and seek replacements or returns."
    },
    {
      "cluster": 31,
      "name": "Poor Customer Service Experience",
      "description": "Customers describe unhelpful, confusing, or rude interactions with support representatives."
    },
    {
      "cluster": 32,
      "name": "General Help Requests with Frustration",
      "description": "Customers post vague or angry pleas for assistance on technical or account issues."
    },
    {
      "cluster": 33,
      "name": "Delayed Refunds After Returns",
      "description": "Customers have been promised refunds that have not arrived within the expected timeframe."
    },
    {
      "cluster": 34,
      "name": "Order Cancellation Failures",
      "description": "Customers encounter errors or timing problems when trying to cancel orders."
    },
    {
      "cluster": 35,
      "name": "Severe Customer Service Dissatisfaction",
      "description": "Customers express extreme frustration with the overall quality and attitude of support staff."
    }
  ]
}
